  "summary": "string",
  "dominant_emotion": "string",
  "resolution_status": "resolved|partially_resolved|unresolved|escalated",
  "escalation_risk": "low|medium|high",
  "conversation_quality": 0-100,
  "customer": { "sentiment": "positive|negative|neutral", "frustration": 0-100, "satisfaction": 0-100 },
  "agent": { "sentiment": "positive|negative|neutral", "empathy": 0-100, "professionalism": 0-100 },
  "sentences": [
    { "speaker": "customer|agent", "text": "string", "sentiment": "positive|negative|neutral", "score": -1.0 to 1.0, "emotion": "string", "reason": "string" }
  ]
}

